/// C1 lessons 391-420: advanced presentations, literary analysis and strategic communication.
class C1MasteryCourseData {
 static List<String> _rotate(List<String> v,int a)=>List<String>.generate(v.length,(i)=>v[(i-a+v.length)%v.length]);
 static B1Question _q(String p,List<String> o,int a,String e)=>B1Question(p,_rotate(o,a),a,e);
 static B1Lesson _build(_Spec s){final n=s.number;final w=[s.meaning,'التعبير عن المكان','التعبير عن الزمن الماضي','طلب الإذن'];final tr=[s.translation,'لم يبدأ الاجتماع بعد.','سأعود إلى المنزل غداً.','لا تتضمن الجملة هذا المعنى.'];final fm=[s.form,'geçmiş zaman','istek kipi','yer tamlayıcısı'];final fn=[s.functionText,'تحديد المكان فقط','تغيير زمن الجملة فقط','تكوين سؤال عن السعر'];return B1Lesson(unitId:s.unitId,globalNumber:n,title:s.title,goal:s.goal,rule:s.rule,examples:[s.sentence+' | '+s.translation,s.example],dialogue:s.dialogue,speakingTask:s.task,questions:[_q('ما معنى «${s.term}»؟',w,n%4,'«${s.term}» تعني: ${s.meaning}.'),_q('ما ترجمة الجملة التركية؟',tr,(n+1)%4,s.translation),_q('أي تعبير يرتبط بمهارة الدرس؟',fm,(n+2)%4,'التعبير المستهدف «${s.form}». '+s.rule),_q('ما الوظيفة التواصلية الأساسية؟',fn,(n+3)%4,s.functionText),_q('أي ممارسة تثبت إتقان المهارة؟',[s.task,'حفظ كلمات دون سياق','نسخ نص دون فهم','تجاهل القرائن والأدلة'],(n+1)%4,s.task)]);}
 static final List<B1Lesson> lessons=[
_Spec(unitId:'c1-u10',number:391,title:'بناء عرض أكاديمي متقدم',goal:'تنظيم عرض طويل حول أطروحة واضحة وتسلسل مقنع.',rule:'ابدأ بالهدف والخريطة، ثم قدم المحاور بانتقالات صريحة، واختم بالنتائج والأسئلة.',term:'sunum akışı',meaning:'تسلسل العرض',sentence:'Sunumun akışını araştırma sorusundan sonuçlara doğru düzenledim.',translation:'نظمت تسلسل العرض من سؤال البحث إلى النتائج.',form:'sunum yapısını kurmak',functionText:'بناء هيكل عرض واضح ومترابط.',task:'أعد مخطط عرض من عشر دقائق مع مقدمة وثلاثة محاور وخاتمة.',example:'Sunumun ana bölümlerini önceden planladım.|خططت أقسام العرض الرئيسة مسبقاً.',dialogue:'A: Sunuma nereden başlayalım؟ — من أين نبدأ العرض؟\nB: Önce amacı ve temel soruyu açıklayalım. — لنوضح الهدف والسؤال الرئيس أولاً.'),
_Spec(unitId:'c1-u10',number:392,title:'الانتقالات بين محاور العرض',goal:'ربط أجزاء العرض بعبارات انتقال تحفظ ترابط الحجة.',rule:'لخص النقطة السابقة بجملة ثم مهد للمحور التالي بعلاقة منطقية واضحة.',term:'geçiş ifadesi',meaning:'عبارة انتقالية',sentence:'Şimdi bulguların olası sonuçlarına geçmek istiyorum.',translation:'أود الآن الانتقال إلى النتائج المحتملة لهذه النتائج.',form:'konular arasında geçiş',functionText:'الانتقال المنطقي بين المحاور.',task:'أعد كتابة عرض قصير وأضف انتقالات مناسبة بين فقراته.',example:'Bölümler arasında doğal geçişler kullandım.|استخدمت انتقالات طبيعية بين الأقسام.',dialogue:'A: Yeni bölüme nasıl geçelim؟ — كيف ننتقل إلى القسم الجديد؟\nB: Önce önceki bulguyu kısaca özetleyelim. — لنلخص النتيجة السابقة بإيجاز.'),
_Spec(unitId:'c1-u10',number:393,title:'شرح الرسوم والبيانات المعقدة',goal:'تفسير الرسم البياني والاتجاهات والاستثناءات بدقة شفوية.',rule:'صف المحاور والوحدات والفترة أولاً، ثم الاتجاه والفروق، ولا تستنتج ما لا تعرضه البيانات.',term:'grafiği yorumlamak',meaning:'يفسر الرسم البياني',sentence:'Grafikteki artış, ikinci çeyrekte belirgin biçimde yavaşlıyor.',translation:'يتباطأ الارتفاع الظاهر في الرسم بوضوح خلال الربع الثاني.',form:'veri görselleştirmesi',functionText:'شرح البيانات المرئية مع حدودها.',task:'اشرح رسماً افتراضياً في دقيقة مع ذكر اتجاه واستثناء وحد واحد.',example:'Grafiği yalnızca görünen verilerle açıkladım.|شرحت الرسم اعتماداً على البيانات الظاهرة فقط.',dialogue:'A: Bu grafik neyi kanıtlıyor؟ — ماذا يثبت هذا الرسم؟\nB: Yalnızca belirtilen dönemdeki eğilimi gösteriyor. — يظهر الاتجاه في الفترة المحددة فقط.'),
_Spec(unitId:'c1-u10',number:394,title:'الإجابة عن الاعتراضات أثناء العرض',goal:'الاستجابة للاعتراض دون فقدان تسلسل العرض أو الموقف.',rule:'استمع إلى الاعتراض كاملاً، أعد صياغته للتأكد، ثم أجب بدليل أو وضح حدود الإجابة.',term:'itiraza yanıt vermek',meaning:'يرد على اعتراض',sentence:'Sorunuzu doğru anladıysam, veri setinin kapsamını sorguluyorsunuz.',translation:'إذا فهمت سؤالك بشكل صحيح، فأنت تتساءل عن نطاق مجموعة البيانات.',form:'soruya kanıtla yanıt',functionText:'الرد على الاعتراض بعد فهمه وتحديده.',task:'تدرب على ثلاثة اعتراضات مفاجئة وأجب عنها بهدوء وأدلة.',example:'İtiraza doğrudan ve ölçülü yanıt verdim.|أجبت عن الاعتراض مباشرة وباعتدال.',dialogue:'A: Örneklem neden bu kadar küçük؟ — لماذا العينة صغيرة إلى هذا الحد؟\nB: Bu sınırlılığı kabul ediyor ve etkisini açıklıyorum. — أقر بهذا القيد وأوضح أثره.'),
_Spec(unitId:'c1-u10',number:395,title:'الأسئلة البلاغية في الخطاب',goal:'تقييم استخدام السؤال البلاغي لتوجيه التفكير لا لطلب معلومة.',rule:'استخدم السؤال البلاغي باعتدال، ثم قدم تفسيراً أو دليلاً حتى لا يبقى غامضاً.',term:'retorik soru',meaning:'سؤال بلاغي',sentence:'Asıl soru, bu değişimin kimler için sürdürülebilir olduğudur.',translation:'السؤال الحقيقي هو: لمن يكون هذا التغيير مستداماً؟',form:'düşünmeye yöneltmek',functionText:'توجيه الجمهور إلى قضية محورية.',task:'أعد صياغة فقرة وأضف سؤالاً بلاغياً يخدم حجتها.',example:'Retorik soruyla dinleyicinin dikkatini topladım.|جمعت انتباه المستمع بالسؤال البلاغي.',dialogue:'A: Bu soru yanıt bekliyor mu؟ — هل ينتظر هذا السؤال إجابة؟\nB: Daha çok dinleyiciyi düşünmeye yöneltiyor. — إنه يوجه المستمع إلى التفكير أكثر.'),
_Spec(unitId:'c1-u10',number:396,title:'إدارة الوقت والإيقاع الشفهي',goal:'ضبط سرعة الكلام والوقفات وتوزيع الزمن على أجزاء العرض.',rule:'خصص وقتاً لكل محور، وأبطئ عند المفاهيم المهمة، واترك وقفة بعد النتيجة الرئيسة.',term:'konuşma temposu',meaning:'إيقاع الحديث',sentence:'Önemli bulgudan sonra kısa bir duraklama yaptım.',translation:'توقفت وقفة قصيرة بعد النتيجة المهمة.',form:'tempo ve duraklama',functionText:'تنظيم سرعة الحديث والوقفات.',task:'سجل عرضاً قصيراً وقيّم سرعته ووضوح الوقفات.',example:'Konuşma tempomu dinleyiciye göre ayarladım.|ضبطت إيقاع حديثي وفق المستمع.',dialogue:'A: Neden burada durakladın؟ — لماذا توقفت هنا؟\nB: Ana bulgunun vurgulanmasını istedim. — أردت إبراز النتيجة الرئيسة.'),
_Spec(unitId:'c1-u10',number:397,title:'تكييف العرض لجمهور متخصص',goal:'اختيار مستوى المصطلحات والتفاصيل لجمهور خبير.',rule:'افترض معرفة أساسية مشتركة، وركز على المنهج والقيود والنتائج الجديدة بدلاً من التعريفات العامة.',term:'uzman dinleyici',meaning:'مستمع متخصص',sentence:'Uzman dinleyiciler için yöntemsel ayrıntıları daha kapsamlı açıkladım.',translation:'شرحت التفاصيل المنهجية بتوسع أكبر للمستمعين المتخصصين.',form:'uzman düzeyinde sunum',functionText:'مواءمة عمق العرض مع خبرة الجمهور.',task:'قدم الموضوع نفسه بنسختين: عامة ومتخصصة، واشرح الفروق.',example:'Sunumun ayrıntı düzeyini uzmanlara göre belirledim.|حددت مستوى تفاصيل العرض وفق خبرة المتخصصين.',dialogue:'A: Temel kavramları açıklayalım mı؟ — هل نشرح المفاهيم الأساسية؟\nB: Bu kitle için yöntem ayrıntılarına odaklanalım. — لهذا الجمهور لنركز على تفاصيل المنهج.'),
_Spec(unitId:'c1-u10',number:398,title:'إدارة جلسة نقاش جماعية',goal:'توزيع فرص الحديث وتلخيص الآراء المتباينة وإعادة النقاش إلى الهدف.',rule:'ضع قواعد مشاركة واضحة، ووازن الوقت، ولخص نقاط الاتفاق والاختلاف دون تحيز.',term:'panel tartışması',meaning:'نقاش حلقي',sentence:'Her konuşmacıya eşit süre vererek tartışmayı yönettim.',translation:'أدرت النقاش بمنح كل متحدث وقتاً متساوياً.',form:'söz hakkı dağıtımı',functionText:'تنظيم المشاركة وتوازن الحوار.',task:'أدر جلسة نقاش من أربعة مشاركين واكتب ملخصاً محايداً.',example:'Farklı görüşlere dengeli biçimde söz hakkı tanıdım.|منحت الآراء المختلفة فرصة متوازنة للتعبير.',dialogue:'A: Tartışma konudan uzaklaşıyor mu؟ — هل يبتعد النقاش عن الموضوع؟\nB: Ana soruya dönüp görüşleri özetleyelim. — لنعد إلى السؤال الرئيس ونلخص الآراء.'),
_Spec(unitId:'c1-u10',number:399,title:'مراجعة مهارات العرض الأكاديمي',goal:'دمج البناء والانتقالات والبيانات والإجابة عن الأسئلة والإيقاع.',rule:'راجع وضوح الهدف والأدلة والتوقيت والتفاعل، ثم عدل العرض وفق ملاحظات الجمهور.',term:'sunum değerlendirmesi',meaning:'تقييم العرض',sentence:'Sunumumu içerik, süre ve dinleyici etkileşimi açısından değerlendirdim.',translation:'قيّمت عرضي من حيث المحتوى والوقت وتفاعل الجمهور.',form:'sunum ölçütleri',functionText:'تقييم العرض بمعايير متعددة.',task:'نفذ عرضاً تجريبياً واستخدم قائمة معايير لتقييمه.',example:'Sunum performansımı ölçütlere göre geliştirdim.|طورت أداء العرض وفق معايير.',dialogue:'A: En çok hangi alanı geliştirdin؟ — أي جانب طورت أكثر؟\nB: Geçişleri ve soru-cevap bölümünü. — الانتقالات وفقرة الأسئلة والأجوبة.'),
 _Spec(unitId:'c1-u10',number:400,title:'مشروع العرض الأكاديمي',goal:'إنتاج عرض متخصص متكامل يعرض قضية ونتائج وأدلة ويرد على أسئلة الجمهور.',rule:'اجمع بين وضوح الأطروحة وتسلسل المحاور والبيانات الدقيقة والتفاعل مع الأسئلة.',term:'sunum projesi',meaning:'مشروع عرض تقديمي',sentence:'Araştırma sonuçlarını uzman bir dinleyici kitlesine sundum.',translation:'عرضت نتائج البحث على جمهور من المتخصصين.',form:'bütünleşik akademik sunum',functionText:'دمج مهارات العرض والإقناع والتفسير والرد على الأسئلة.',task:'أنجز عرضاً من عشر دقائق مع شرائح ومراجع وجلسة أسئلة.',example:'Sunumumu prova ederek süreyi ve açıklığı geliştirdim.|طورت مدة العرض ووضوحه من خلال التدريب.',dialogue:'A: Sunumun en güçlü yönü neydi؟ — ما أقوى جانب في العرض؟\\nB: Kanıtları açık biçimde sunup soruları yanıtlamak. — عرض الأدلة بوضوح والإجابة عن الأسئلة.'),
_Spec(unitId:'c1-u11',number:401,title:'تحليل وجهة النظر السردية',goal:'تمييز الراوي العليم والمحدود وضمير المتكلم وأثرها في المعلومات.',rule:'اسأل من يرى الأحداث ومن يعرفها، وما الذي يظل محجوباً عن القارئ.',term:'anlatıcı bakış açısı',meaning:'وجهة نظر الراوي',sentence:'Olaylar, anlatıcının sınırlı bilgisi üzerinden aktarılıyor.',translation:'تُنقل الأحداث عبر معرفة الراوي المحدودة.',form:'anlatı perspektifi',functionText:'تحليل زاوية السرد وحدود المعرفة.',task:'قارن فقرتين للحدث نفسه من وجهتي نظر مختلفتين.',example:'Anlatıcının bakış açısının okuru nasıl yönlendirdiğini inceledim.|درست كيف توجه وجهة نظر الراوي القارئ.',dialogue:'A: Okur her şeyi biliyor mu؟ — هل يعرف القارئ كل شيء؟\nB: Hayır, anlatıcının bilgisiyle sınırlı. — لا، معرفته محدودة بمعرفة الراوي.'),
_Spec(unitId:'c1-u11',number:402,title:'بناء الشخصية والتحول النفسي',goal:'استنتاج تطور الشخصية من أفعالها وحوارها وتناقضاتها.',rule:'لا تعتمد على الوصف المباشر وحده؛ تتبع القرارات والتغيرات وردود الفعل عبر النص.',term:'karakter gelişimi',meaning:'تطور الشخصية',sentence:'Karakterin kararları, zamanla değişen değerlerini ortaya koyuyor.',translation:'تكشف قرارات الشخصية عن قيمها المتغيرة مع الوقت.',form:'karakter çözümlemesi',functionText:'تحليل الشخصية وتطور دوافعها.',task:'اكتب تحليلاً يشرح تحول شخصية مع ثلاثة شواهد نصية.',example:'Karakterin dönüşümünü davranışlarıyla açıkladım.|شرحت تحول الشخصية من خلال سلوكها.',dialogue:'A: Karakter neden fikir değiştirdi؟ — لماذا غيرت الشخصية رأيها؟\nB: Yaşadığı olaylar önceliklerini değiştirdi. — غيرت الأحداث التي عاشتها أولوياته.'),
_Spec(unitId:'c1-u11',number:403,title:'الرمز والدلالة في النص الأدبي',goal:'تفسير الرمز وفق تكراره وسياقه وعلاقته بموضوع النص.',rule:'لا تفرض معنى ثابتاً على الرمز؛ اربطه بالصور المحيطة وتطور الحدث.',term:'sembol',meaning:'رمز',sentence:'Kırık saat, öyküde kaybolan zamanı simgeliyor.',translation:'ترمز الساعة المكسورة في القصة إلى الزمن الضائع.',form:'sembolik anlam',functionText:'استخلاص الدلالة الرمزية من السياق.',task:'حلل رمزاً متكرراً في قصة وقدم قرائن لتفسيره.',example:'Sembolün anlamını metnin bütünüyle ilişkilendirdim.|ربطت معنى الرمز بالنص كله.',dialogue:'A: Saat yalnızca bir eşya mı؟ — هل الساعة مجرد غرض؟\nB: Hayır, zaman temasını da temsil ediyor. — لا، إنها تمثل أيضاً موضوع الزمن.'),
_Spec(unitId:'c1-u11',number:404,title:'تحليل الاستعارة الممتدة',goal:'متابعة صورة مجازية تتطور عبر عدة جمل أو فقرات.',rule:'حدد مجال الصورة ثم تتبع عناصرها المتكررة وكيف تسهم في بناء الموضوع.',term:'uzatılmış metafor',meaning:'استعارة ممتدة',sentence:'Yazar, toplumu uzun bir yolculuğa benzeterek değişimi anlatıyor.',translation:'يشبه الكاتب المجتمع برحلة طويلة ليصف التغيير.',form:'metafor ağı',functionText:'شبكة الصور المجازية الممتدة.',task:'حلل استعارة ممتدة في نص وحدد عناصرها ووظيفتها.',example:'Metaforun metin boyunca nasıl geliştiğini gösterdim.|أوضحت كيف تتطور الاستعارة عبر النص.',dialogue:'A: Bu benzetme neden tekrarlandı؟ — لماذا تكرر هذا التشبيه؟\nB: Değişim temasını bütün metinde birleştiriyor. — إنه يربط موضوع التغيير في النص كله.'),
_Spec(unitId:'c1-u11',number:405,title:'تحليل الحجاج في المقالات الفكرية',goal:'استخراج الأطروحة والافتراضات والأدلة والنتيجة في مقال فكري.',rule:'حدد الادعاء الرئيس والافتراضات غير المعلنة ونوع الدليل، ثم قيّم صلة النتيجة بالمقدمات.',term:'entelektüel argüman',meaning:'حجة فكرية',sentence:'Yazarın savı, örtük bir varsayıma dayanıyor.',translation:'تستند حجة الكاتب إلى افتراض ضمني.',form:'argüman çözümlemesi',functionText:'تفكيك الحجة والافتراضات.',task:'حلل مقالاً وحدد الأطروحة وافتراضين ودليلين.',example:'Yazarın varsayımlarını metindeki kanıtlarla karşılaştırdım.|قارنت افتراضات الكاتب بأدلة النص.',dialogue:'A: Bu sonuç öncüllerden çıkıyor mu؟ — هل تنتج هذه النتيجة عن المقدمات؟\nB: Yalnızca bir varsayım kabul edilirse. — فقط إذا قُبل افتراض معين.'),
_Spec(unitId:'c1-u11',number:406,title:'كتابة مراجعة نقدية لعمل أدبي',goal:'تقديم تقييم يوازن بين القيمة الفنية والحدود والأدلة النصية.',rule:'لخص العمل بإيجاز، ثم ناقش عناصره الفنية وادعم التقييم بأمثلة محددة.',term:'eleştirel inceleme',meaning:'مراجعة نقدية',sentence:'Romanın anlatım gücü etkileyici, ancak yan karakterler yeterince geliştirilmemiş.',translation:'قوة السرد في الرواية مؤثرة، لكن الشخصيات الثانوية لم تطور بما يكفي.',form:'gerekçeli eleştiri',functionText:'تقديم نقد مبرر لا انطباع عام.',task:'اكتب مراجعة نقدية من 300 كلمة لعمل قرأته.',example:'Değerlendirmemi metinden örneklerle destekledim.|دعمت تقييمي بأمثلة من النص.',dialogue:'A: Kitabı beğendin mi؟ — هل أعجبك الكتاب؟\nB: Bazı yönlerini başarılı, bazılarını sınırlı buldum. — وجدت بعض جوانبه ناجحة وبعضها محدوداً.'),
_Spec(unitId:'c1-u11',number:407,title:'المقارنة الأسلوبية بين الكتّاب',goal:'تمييز الفروق في المعجم والإيقاع والصورة والمنظور بين كاتبين.',rule:'اختر مقاطع متقاربة في الموضوع وقارن أدوات محددة بدلاً من الأحكام العامة.',term:'üslup karşılaştırması',meaning:'مقارنة أسلوبية',sentence:'İki yazar aynı temayı farklı anlatım teknikleriyle işliyor.',translation:'يعالج الكاتبان الموضوع نفسه بتقنيات سردية مختلفة.',form:'yazarın üslubu',functionText:'مقارنة الخصائص الأسلوبية.',task:'قارن مقطعين وحدد ثلاثة فروق أسلوبية مدعومة بأمثلة.',example:'İki metnin dilsel tercihlerini karşılaştırdım.|قارنت الاختيارات اللغوية للنصين.',dialogue:'A: Hangisi daha etkileyici؟ — أيهما أكثر تأثيراً؟\nB: Amaçlarına göre farklı güçlü yönleri var. — لكل منهما نقاط قوة مختلفة بحسب الهدف.'),
_Spec(unitId:'c1-u11',number:408,title:'الإحالات والتناص بين النصوص',goal:'فهم الإشارات إلى نصوص أو شخصيات أو أفكار سابقة.',rule:'حدد النص المرجعي ووظيفة الإحالة: تكريم أو نقد أو مفارقة أو توسيع للمعنى.',term:'metinlerarasılık',meaning:'التناص',sentence:'Şair, eski bir destana gönderme yaparak çağdaş bir sorunu tartışıyor.',translation:'يناقش الشاعر قضية معاصرة بالإشارة إلى ملحمة قديمة.',form:'metinlerarası gönderme',functionText:'تفسير العلاقة بين النصوص.',task:'حدد إحالتين في نص واشرح أثر كل منهما.',example:'Metinlerarası ilişkiyi bağlam içinde yorumladım.|فسرت العلاقة بين النصوص ضمن السياق.',dialogue:'A: Okur eski metni bilmek zorunda mı؟ — هل يجب أن يعرف القارئ النص القديم؟\nB: Bilmesi yorumu derinleştirir, ancak bağlam ipucu verir. — معرفته تعمق التفسير لكن السياق يقدم قرائن.'),
_Spec(unitId:'c1-u11',number:409,title:'الفروق الدقيقة في الترجمة الأدبية',goal:'نقل النبرة والإيقاع والصورة دون التضحية بالمعنى.',rule:'قارن البدائل بحسب الدلالة والإيقاع والسجل، ووضح سبب اختيارك عند تعذر التطابق الكامل.',term:'edebî çeviri',meaning:'ترجمة أدبية',sentence:'Çeviride sözcük anlamının yanı sıra anlatım tonu da korunmalı.',translation:'ينبغي الحفاظ في الترجمة على نبرة التعبير إلى جانب معنى الكلمات.',form:'çeviri tercihi',functionText:'اتخاذ قرار ترجمي يوازن المعنى والأسلوب.',task:'ترجم فقرة أدبية بطريقتين وقارن أثر كل صياغة.',example:'Çeviri tercihlerimi gerekçeleriyle açıkladım.|شرحت اختياراتي الترجمية مع أسبابها.',dialogue:'A: Her sözcüğü aynı biçimde çevirdin mi؟ — هل ترجمت كل كلمة بالطريقة نفسها؟\nB: Hayır, anlamı ve tonu birlikte korudum. — لا، حافظت على المعنى والنبرة معاً.'),
_Spec(unitId:'c1-u11',number:410,title:'مراجعة التحليل الأدبي والأسلوبي',goal:'دمج تحليل السرد والرمز والحجاج والأسلوب والتناص.',rule:'اربط كل تفسير بشاهد، وميز بين وصف التقنية وتقييم أثرها.',term:'edebî çözümleme',meaning:'تحليل أدبي',sentence:'Metnin biçimsel özelliklerini temasıyla birlikte değerlendirdim.',translation:'قيّمت الخصائص الشكلية للنص مع موضوعه.',form:'bütünlüklü metin çözümlemesi',functionText:'تحليل النص من جوانبه المتكاملة.',task:'اكتب تحليلاً أدبياً يجمع أربعة عناصر من الوحدة.',example:'Yorumlarımı metinsel kanıtlarla temellendirdim.|أسست تفسيري على أدلة نصية.',dialogue:'A: Yalnızca temayı mı inceledin؟ — هل درست الموضوع فقط؟\nB: Biçim, anlatıcı ve sembolleri de değerlendirdim. — قيمت الشكل والراوي والرموز أيضاً.'),
_Spec(unitId:'c1-u12',number:411,title:'صياغة توصية استراتيجية',goal:'تحويل تحليل معقد إلى توصية قابلة للتنفيذ لصانع القرار.',rule:'اربط التوصية بهدف واضح ودليل ومخاطر وموارد ومؤشر متابعة.',term:'stratejik tavsiye',meaning:'توصية استراتيجية',sentence:'Önerilen yaklaşım, maliyetleri azaltırken uygulama riskini de sınırlandırıyor.',translation:'يقلل النهج المقترح التكاليف ويحد في الوقت نفسه من مخاطر التنفيذ.',form:'stratejik öneri',functionText:'تحويل التحليل إلى قرار عملي.',task:'اكتب توصية استراتيجية من صفحة واحدة تتضمن مؤشرات قياس.',example:'Öneriyi uygulanabilir adımlara dönüştürdüm.|حولت التوصية إلى خطوات قابلة للتنفيذ.',dialogue:'A: Önerinin başarısını nasıl izleyeceğiz؟ — كيف نتابع نجاح التوصية؟\nB: Ölçülebilir göstergeler ve düzenli raporlarla. — بمؤشرات قابلة للقياس وتقارير دورية.'),
_Spec(unitId:'c1-u12',number:412,title:'التواصل في الأزمات',goal:'تقديم معلومات دقيقة ومتعاطفة مع توضيح ما هو معروف وما لم يتأكد.',rule:'ابدأ بالمعلومة المؤكدة والإجراء الجاري، وتجنب التخمين وحدد موعد التحديث التالي.',term:'kriz iletişimi',meaning:'التواصل أثناء الأزمة',sentence:'Doğrulanmış bilgileri paylaşıp belirsiz noktaları açıkça belirttik.',translation:'شاركنا المعلومات المتحقق منها وحددنا النقاط غير المؤكدة بوضوح.',form:'şeffaf bilgilendirme',functionText:'التواصل الواضح في الظروف الحساسة.',task:'اكتب بياناً أولياً لأزمة افتراضية مع حقائق مؤكدة وخطوة تالية.',example:'Kriz mesajında açık ve tutarlı bir dil kullandım.|استخدمت لغة واضحة ومتسقة في رسالة الأزمة.',dialogue:'A: Henüz doğrulanmayan bilgileri paylaşalım mı؟ — هل نشارك المعلومات غير المؤكدة؟\nB: Hayır, doğrulanana kadar beklemeliyiz. — لا، يجب أن ننتظر حتى يتم التحقق.'),
_Spec(unitId:'c1-u12',number:413,title:'إدارة أصحاب المصلحة',goal:'تحليل توقعات الأطراف المتأثرة وبناء خطة تواصل مناسبة.',rule:'حدد نفوذ كل طرف واهتمامه ومخاوفه، ثم اختر مستوى المشاركة والرسالة الملائمة.',term:'paydaş analizi',meaning:'تحليل أصحاب المصلحة',sentence:'Her paydaşın beklentisini ve karar üzerindeki etkisini değerlendirdik.',translation:'قيّمنا توقعات كل صاحب مصلحة وتأثيره في القرار.',form:'paydaş yönetimi',functionText:'تنظيم التواصل مع الأطراف المعنية.',task:'أنشئ خريطة أصحاب مصلحة وخطة تواصل لأربعة أطراف.',example:'Paydaşların önceliklerine göre iletişim planı hazırladım.|أعددت خطة تواصل وفق أولويات أصحاب المصلحة.',dialogue:'A: Herkese aynı mesajı mı göndereceğiz؟ — هل نرسل الرسالة نفسها للجميع؟\nB: Ana bilgi aynı, ayrıntı düzeyi farklı olacak. — المعلومة الأساسية واحدة لكن مستوى التفاصيل سيختلف.'),
_Spec(unitId:'c1-u12',number:414,title:'حل النزاع والتوصل إلى قرار',goal:'تحويل الخلاف إلى نقاط قابلة للنقاش ثم بناء بدائل واتفاق.',rule:'افصل الأشخاص عن المشكلة، وحدد المصالح، واطلب معايير مشتركة لتقييم الحلول.',term:'çatışma çözümü',meaning:'حل النزاع',sentence:'Taraflar, ortak ölçütler belirleyerek anlaşmazlığı çözdü.',translation:'حل الأطراف الخلاف عبر تحديد معايير مشتركة.',form:'uzlaşma süreci',functionText:'إدارة الخلاف للوصول إلى حل.',task:'اكتب خطة من خمس خطوات لحل نزاع مهني.',example:'Sorunu kişiselleştirmeden çözüm seçeneklerini değerlendirdim.|قيّمت خيارات الحل دون تحويل المشكلة إلى خلاف شخصي.',dialogue:'A: Hangi noktada anlaşamıyoruz؟ — في أي نقطة نختلف؟\nB: Öncelikleri farklı tanımlıyoruz; ölçütleri netleştirelim. — نحدد الأولويات بشكل مختلف؛ لنوضح المعايير.'),
_Spec(unitId:'c1-u12',number:415,title:'تقديم إحاطة تنفيذية مختصرة',goal:'عرض قرار أو وضع معقد في دقائق مع إبراز المطلوب من الإدارة.',rule:'ابدأ بالخلاصة والقرار المطلوب، ثم ثلاثة أدلة ومخاطر وخطوة تالية.',term:'yönetici bilgilendirmesi',meaning:'إحاطة إدارية',sentence:'Yönetim için temel bulguları ve karar seçeneklerini özetledim.',translation:'لخصت النتائج الأساسية وخيارات القرار للإدارة.',form:'kısa yönetici sunumu',functionText:'تقديم إحاطة مركزة لصانع القرار.',task:'قدم إحاطة من ثلاث دقائق تنتهي بطلب قرار محدد.',example:'Yönetici sunumunda ayrıntı yerine karara odaklandım.|ركزت في العرض الإداري على القرار بدلاً من التفاصيل.',dialogue:'A: Ayrıntılı raporu okuyalım mı؟ — هل نقرأ التقرير التفصيلي؟\nB: Önce karar özetini sunalım. — لنقدم ملخص القرار أولاً.'),
_Spec(unitId:'c1-u12',number:416,title:'الإرشاد والتغذية الراجعة المهنية',goal:'تقديم توجيه يساعد المتعلم أو الزميل على تحسين أدائه.',rule:'حدد السلوك الملحوظ وأثره ثم اقترح خطوة قابلة للتطبيق وتابع التقدم.',term:'mentorluk',meaning:'إرشاد مهني',sentence:'Geri bildirimi belirli örnekler ve uygulanabilir önerilerle verdim.',translation:'قدمت التغذية الراجعة بأمثلة محددة ومقترحات قابلة للتطبيق.',form:'gelişim odaklı geri bildirim',functionText:'توجيه التحسين بخطوات واضحة.',task:'صمم جلسة إرشاد قصيرة تتضمن نقطة قوة وهدف تطوير ومتابعة.',example:'Gelişim hedefini birlikte belirledik.|حددنا هدف التطور معاً.',dialogue:'A: Nereden başlamalıyım؟ — من أين أبدأ؟\nB: Önce güçlü yönünü kullanıp tek bir beceriye odaklan. — استخدم نقطة قوتك وركز على مهارة واحدة.'),
_Spec(unitId:'c1-u12',number:417,title:'محاكاة التواصل المهني المتكامل',goal:'دمج التوصية الاستراتيجية وإدارة الأزمة والتفاوض والإحاطة.',rule:'حافظ على اتساق المعلومات بين الرسائل والاجتماعات والقرارات، وحدد المسؤوليات بوضوح.',term:'bütünleşik mesleki iletişim',meaning:'تواصل مهني متكامل',sentence:'Farklı iletişim kanallarında aynı karar çerçevesini koruduk.',translation:'حافظنا على إطار القرار نفسه عبر قنوات التواصل المختلفة.',form:'kurumsal tutarlılık',functionText:'الحفاظ على اتساق التواصل المؤسسي.',task:'نفذ محاكاة تشمل أزمة واجتماعاً ومفاوضات وإحاطة نهائية.',example:'Süreci farklı paydaşlarla tutarlı biçimde yönettim.|أدرت العملية باتساق مع مختلف أصحاب المصلحة.',dialogue:'A: Mesajlar arasında çelişki var mı؟ — هل يوجد تناقض بين الرسائل؟\nB: Hepsini aynı karar kaydına göre kontrol ettik. — تحققنا منها جميعاً وفق سجل القرار نفسه.'),
_Spec(unitId:'c1-u12',number:418,title:'المراجعة النهائية لمهارات C1',goal:'تقييم الأداء في اللغة الرسمية والبحث والقراءة والاستماع والتحدث.',rule:'استخدم عينات أداء ومعايير واضحة لتحديد نقاط القوة والفجوات والخطوة التالية.',term:'C1 yeterlilik değerlendirmesi',meaning:'تقييم كفاءة C1',sentence:'Dört becerideki performansımı ölçütlere göre gözden geçirdim.',translation:'راجعت أدائي في المهارات الأربع وفق معايير.',form:'öz değerlendirme ölçütleri',functionText:'تقييم الكفاءة وفق أدلة عملية.',task:'أنشئ تقريراً ذاتياً يقيّم المهارات الأربع بأمثلة ملموسة.',example:'Gelişim alanlarımı kanıtlara dayanarak belirledim.|حددت مجالات التطور استناداً إلى الأدلة.',dialogue:'A: Kendini nasıl değerlendirdin؟ — كيف قيمت نفسك؟\nB: Gerçek görevlerden aldığım örneklerle. — بأمثلة من مهام واقعية.'),
_Spec(unitId:'c1-u12',number:419,title:'المشروع الختامي الشامل لمستوى C1',goal:'إنتاج مشروع يجمع البحث والتحليل والكتابة والعرض والتواصل المهني.',rule:'اختر قضية معقدة، اجمع مصادر موثوقة، حللها، اكتب تقريراً، ثم اعرض توصية وتفاعل مع الأسئلة.',term:'C1 bitirme projesi',meaning:'مشروع التخرج لمستوى C1',sentence:'Araştırma, rapor ve sunumu tek bir bütünleşik projede birleştirdim.',translation:'جمعت البحث والتقرير والعرض في مشروع متكامل واحد.',form:'bütünleşik bitirme çalışması',functionText:'إثبات إتقان مهارات C1 في مشروع شامل.',task:'أنجز مشروعاً نهائياً يتضمن تقريراً وعرضاً وملف أدلة وتقييماً ذاتياً.',example:'C1 düzeyindeki becerilerimi özgün bir projeyle gösterdim.|أظهرت مهارات مستوى C1 بمشروع أصيل.',dialogue:'A: Proje hangi becerileri birleştiriyor؟ — ما المهارات التي يجمعها المشروع؟\nB: Araştırma, eleştirel okuma, yazma ve sunum. — البحث والقراءة النقدية والكتابة والعرض.'),
 _Spec(unitId:'c1-u12',number:420,title:'مراجعة ملف الإنجاز النهائي',goal:'تنظيم ملف الإنجاز وإثبات الكفاءة في مهارات C1 بأدلة منتقاة.',rule:'يضم الملف نماذج متنوعة ومعايير تقييم وتأملاً في التطور وأهدافاً مستقبلية قابلة للمتابعة.',term:'portfolyo değerlendirmesi',meaning:'تقييم ملف الإنجاز',sentence:'Portfolyomda en güçlü çalışmalarımı ve gelişim notlarımı bir araya getirdim.',translation:'جمعت في ملف إنجازي أفضل أعمالي وملاحظات تطوري.',form:'kanıta dayalı öz değerlendirme',functionText:'توثيق الكفاءة والتطور باستخدام عينات أداء ومعايير واضحة.',task:'راجع ملفك واختر ستة أعمال تمثل المهارات الأربع مع تفسير سبب اختيار كل عمل.',example:'Portfolyomdaki her çalışma belirli bir beceriyi gösteriyor.|يمثل كل عمل في ملف إنجازي مهارة محددة.',dialogue:'A: Portfolyoyu nasıl tamamladın؟ — كيف أكملت ملف الإنجاز؟\\nB: Çalışmaları ölçütlere göre seçip gelişimimi açıkladım. — اخترت الأعمال وفق المعايير وشرحت تطوري.'),
 ].map(_build).toList(growable:false);
}
